import sys

class Player:
    def __init__(self):
        self.__name = ""
        self.__id = 0
        self.__power = 0

    def input(self):
        parts = sys.stdin.readline().split()
        self.__name = parts[0]
        self.__id = int(parts[1])
        self.__power = int(parts[2])

    def boost(self, amount):
        self.__power += amount

    def attack(self, amount):
        self.__power -= amount
        if self.__power < 0:
            self.__power = 0

    def display(self):
        return f"Name: {self.__name}, ID: {self.__id}, Power: {self.__power}"

def main():
    n = int(sys.stdin.readline().strip())
    players = []

    for _ in range(n):
        p = Player()
        p.input()
        players.append(p)

    amount_line = sys.stdin.readline().split()
    boost_amount = int(amount_line[0])
    attack_amount = int(amount_line[1])

    for p in players:
        p.boost(boost_amount)
        p.attack(attack_amount)

    print("Final Player Stats:")
    for p in players:
        print(p.display())

if __name__ == "__main__":
    main()
